import { Group, Mesh, PlaneGeometry, MeshBasicNodeMaterial, MeshStandardNodeMaterial } from 'three/webgpu';
import { uv, mix, color } from 'three/tsl';
import { gsap } from 'gsap';
import {} from '@/primitives';
import {} from '@/text';

export default function createNode(config, ctx) {
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];

  const container = new Group();
  container.userData.handlers = {};
  const cleanupFns = [];

  // Background rail with vertical gradient
  const railGeom = new PlaneGeometry(3.6, 0.5);
  const railMat = new MeshBasicNodeMaterial({
    color: mix(color('#1b1b23'), color('#101015'), uv().y),
    transparent: false,
  });
  const railMesh = new Mesh(railGeom, railMat);
  railMesh.position.z = 0.15;
  container.add(railMesh);
  cleanupFns.push(() => {
    railGeom.dispose();
    railMat.dispose();
  });

  // Contact shadow plane
  const shadowGeom = new PlaneGeometry(3.6, 0.5);
  const shadowMat = new MeshBasicNodeMaterial({
    color: 0x000000,
    transparent: true,
    opacity: 0.35,
  });
  const shadowMesh = new Mesh(shadowGeom, shadowMat);
  shadowMesh.position.z = -0.01;
  shadowMesh.position.y = -0.06;
  container.add(shadowMesh);
  cleanupFns.push(() => {
    shadowGeom.dispose();
    shadowMat.dispose();
  });

  // Underline bar for active entry
  const underlineGeom = new PlaneGeometry(0.28, 0.025);
  const underlineMat = new MeshStandardNodeMaterial({
    emissive: 0xff2a38,
    emissiveIntensity: 1.8,
    metalness: 0,
    roughness: 0.5,
    transparent: true,
    opacity: 1,
  });
  const underlineMesh = new Mesh(underlineGeom, underlineMat);
  underlineMesh.position.z = 0.02;
  underlineMesh.position.y = -0.06;
  container.add(underlineMesh);
  cleanupFns.push(() => {
    underlineGeom.dispose();
    underlineMat.dispose();
  });

  // Create navigation entries
  const entryGroups = [];
  items.forEach((item, i) => {
    const isActive = item.role === 'nav-active';
    const entry = new Group();
    entry.position.x = (i - 2) * 0.68;
    entry.position.y = 0;
    entry.position.z = 0;
    container.add(entry);
    entryGroups.push(entry);

    const txt = ctx.fontAtlas.createText(item.text, {
      fontSize: item.typography?.fontSize ?? 13,
      color: isActive ? '#e8ecf2' : '#a6adba',
      align: 'center',
    });
    entry.add(txt);

    // Find the mesh inside the text object to animate its material color
    let textMesh = null;
    txt.traverse((obj) => {
      if (obj.isMesh) textMesh = obj;
    });

    // Hover handlers for inactive items
    if (!isActive && textMesh) {
      entry.userData.handlers.hoverEnter = () => {
        gsap.to(textMesh.material.color, {
          r: 0xe8 / 0xec / 0xf2,
          g: 0xe8 / 0xec / 0xf2,
          b: 0xe8 / 0xec / 0xf2,
          duration: 0.16,
          ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
        });
      };
      entry.userData.handlers.hoverLeave = () => {
        gsap.to(textMesh.material.color, {
          r: 0xa6 / 0xad / 0xba,
          g: 0xa6 / 0xad / 0xba,
          b: 0xa6 / 0xad / 0xba,
          duration: 0.16,
          ease: 'cubic-bezier(0.25,0.46,0.45,0.94)',
        });
      };
    }

    // Press-down affordance
    entry.userData.handlers.press = () => {
      gsap.to(entry.scale, {
        x: 0.97,
        y: 0.97,
        z: 0.97,
        duration: 0.12,
        ease: 'cubic-bezier(0.175,0.885,0.32,1.275)',
      });
      gsap.to(entry.position, {
        z: -0.03,
        duration: 0.12,
        ease: 'cubic-bezier(0.175,0.885,0.32,1.275)',
      });
    };
    entry.userData.handlers.release = () => {
      gsap.to(entry.scale, {
        x: 1,
        y: 1,
        z: 1,
        duration: 0.12,
        ease: 'power3.out',
      });
      gsap.to(entry.position, {
        z: 0,
        duration: 0.12,
        ease: 'power3.out',
      });
    };

    // Position underline under active entry
    if (isActive) {
      underlineMesh.position.x = entry.position.x;
    }
  });

  // Mount rise‑in animation
  const mountTL = gsap.timeline();
  mountTL.from(container.position, {
    y: 0.4,
    duration: 0.7,
    ease: 'power3.out',
  });
  cleanupFns.push(() => mountTL.kill());

  // Cleanup function
  container.userData.cleanup = () => {
    cleanupFns.forEach((fn) => fn());
    container.traverse((obj) => {
      if (obj.geometry) obj.geometry.dispose();
      if (obj.material) {
        if (Array.isArray(obj.material)) {
          obj.material.forEach((m) => m.dispose());
        } else {
          obj.material.dispose();
        }
      }
    });
  };

  return container;
}
